import os, json
from flask import Flask, jsonify
import psycopg2, redis

app = Flask(__name__)
cache = redis.Redis.from_url(os.environ['REDIS_URL'])

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/users')
def users():
    cached = cache.get('users')
    if cached:
        return jsonify({'source': 'cache', 'data': json.loads(cached)})
    conn = psycopg2.connect(os.environ['DATABASE_URL'])
    cur = conn.cursor()
    cur.execute('SELECT id, username, email FROM users')
    rows = [{'id': r[0], 'username': r[1], 'email': r[2]} for r in cur.fetchall()]
    conn.close()
    cache.setex('users', 60, json.dumps(rows))
    return jsonify({'source': 'db', 'data': rows})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
