```go
// Go 语言版本（生产推荐使用 tenacity 或 backoff 库）
package main

import (
    "database/sql"
    "fmt"
    "math"
    "time"
)

func connectWithRetry(dsn string, maxRetries int) (*sql.DB, error) {
    for i := 0; i < maxRetries; i++ {
        db, err := sql.Open("postgres", dsn)
        if err == nil {
            if err = db.Ping(); err == nil {
                fmt.Printf("Connected on attempt %d\n", i+1)
                return db, nil
            }
        }
        delay := time.Duration(math.Pow(2, float64(i))) * time.Second
        if delay > 60*time.Second { delay = 60 * time.Second }
        fmt.Printf("Attempt %d failed, retrying in %v...\n", i+1, delay)
        time.Sleep(delay)
    }
    return nil, fmt.Errorf("failed after %d retries", maxRetries)
}
